// Some portions generated by Co-Pilot
"use client";

import Image from "next/image";
import { useTranslations } from "next-intl";
import {
  useCallback,
  useRef,
  useState,
  useSyncExternalStore,
  type HTMLAttributes,
} from "react";
import { FiPause, FiPlay } from "react-icons/fi";
import Slider from "react-slick";
import adoptersData from "@/data/adopters.json";
import { shuffle } from "@/utils/shuffle";

import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

interface Adopter {
  name: string;
  url: string;
  featured?: boolean;
  logo_white?: string;
  logoDisplay?: {
    src?: string;
    maxWidth?: number;
    height?: number;
    monochrome?: boolean;
  };
}

interface LogoSlideProps extends HTMLAttributes<HTMLDivElement> {
  adopter: Adopter;
}

const featuredAdopters: Adopter[] = adoptersData.filter(
  (adopter) => adopter.featured,
);
const subscribe = () => () => {};
const getClientSnapshot = () => true;
const getServerSnapshot = () => false;
const motionQuery = "(prefers-reduced-motion: reduce)";
const getMotionSnapshot = () => window.matchMedia(motionQuery).matches;
const subscribeToMotion = (onChange: () => void) => {
  const query = window.matchMedia(motionQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};

const LogoSlide = ({ adopter, ...props }: LogoSlideProps) => (
  <div {...props}>
    <a
      href={adopter.url}
      className="flex h-16 items-center justify-center rounded px-3 opacity-60 transition-opacity hover:opacity-100 focus-visible:opacity-100 focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-pink"
    >
      <span
        className="relative block w-full"
        style={{
          maxWidth: adopter.logoDisplay?.maxWidth ?? 144,
          height: adopter.logoDisplay?.height ?? 48,
        }}
      >
        <Image
          fill
          sizes="(max-width: 639px) 40vw, 144px"
          src={`/images/${adopter.logoDisplay?.src ?? adopter.logo_white}`}
          alt={adopter.name}
          className={`object-contain${adopter.logoDisplay?.monochrome ? " brightness-0 invert" : ""}`}
        />
      </span>
    </a>
  </div>
);

const LogoCarousel = () => {
  const t = useTranslations("LogoCarousel");
  const hydrated = useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
  const reducedMotion = useSyncExternalStore(
    subscribeToMotion,
    getMotionSnapshot,
    getClientSnapshot,
  );
  const [shuffledAdopters] = useState(() => shuffle([...featuredAdopters]));
  const [paused, setPaused] = useState(false);
  const adopters = hydrated ? shuffledAdopters : featuredAdopters;
  const carouselRef = useRef<HTMLDivElement>(null);
  const updateSlideAccessibility = useCallback(() => {
    // Slick wraps custom slides, so its generated hidden slides must be made inert.
    carouselRef.current
      ?.querySelectorAll<HTMLElement>(".slick-slide")
      .forEach((slide) => {
        slide.inert = slide.getAttribute("aria-hidden") === "true";
      });
  }, []);

  return (
    <div ref={carouselRef} className="mx-auto w-full max-w-6xl py-8 lg:py-10">
      <div className="relative flex min-h-11 items-center justify-center px-12">
        <h2 className="mb-0 text-center text-sm font-normal text-grey">
          {t("title")}
        </h2>
        {!reducedMotion && (
          <button
            type="button"
            aria-label={t(paused ? "play" : "pause")}
            onClick={() => setPaused((value) => !value)}
            className="absolute right-0 flex h-11 w-11 items-center justify-center rounded-full border border-white/10 text-grey transition-colors hover:border-white/30 hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
          >
            {paused ? (
              <FiPlay aria-hidden="true" />
            ) : (
              <FiPause aria-hidden="true" />
            )}
          </button>
        )}
      </div>
      <Slider
        dots={false}
        infinite={adopters.length > 6}
        arrows={false}
        slidesToShow={6}
        slidesToScroll={1}
        autoplay={hydrated && !paused && !reducedMotion}
        pauseOnHover
        pauseOnFocus
        onInit={updateSlideAccessibility}
        onReInit={updateSlideAccessibility}
        speed={2000}
        autoplaySpeed={2500}
        cssEase="linear"
        responsive={[
          { breakpoint: 1024, settings: { slidesToShow: 4 } },
          { breakpoint: 768, settings: { slidesToShow: 3 } },
          { breakpoint: 480, settings: { slidesToShow: 2 } },
        ]}
        className="mt-4"
      >
        {adopters.map((adopter) => (
          <LogoSlide key={adopter.name} adopter={adopter} />
        ))}
      </Slider>
    </div>
  );
};

export default LogoCarousel;
